observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_4876eb9e2df5d63b>
    <urn:graphragprov:unit:u_5c0ffa968a5e9842>
    <urn:graphragprov:unit:u_8749a7cc9b8f0016>
    <urn:graphragprov:unit:u_b95084ac6a54a5a7>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
